jobs={
 'R017':{'dur':7,'starts':range(2,6)},
 'R018':{'dur':7,'starts':range(4,9)},
 'R025':{'dur':7,'starts':range(15,19)},
 'R026':{'dur':7,'starts':range(17,22)},
}
occ=[0]*40
sol={}
order=sorted(jobs,key=lambda j:(len(list(jobs[j]['starts'])),jobs[j]['dur']))
def bt(i=0):
    if i==len(order):
        print(sol); raise SystemExit
    name=order[i]
    for s in jobs[name]['starts']:
        if all(occ[t]<2 for t in range(s,s+jobs[name]['dur'])):
            sol[name]=s
            for t in range(s,s+jobs[name]['dur']): occ[t]+=1
            bt(i+1)
            for t in range(s,s+jobs[name]['dur']): occ[t]-=1
            del sol[name]
try:
    bt()
except SystemExit:
    raise
print('none')
PY"

